"""Information content of Gauss-sum features: magnitude versus sign.

Estimates the mutual information, in bits, between a Gauss-sum feature and the residue
class of the modulus, over a sample of odd primes.  The magnitude feature is provably
constant (|g| = sqrt(p) for every twist), so its mutual information must be exactly zero;
the sign of g^2 is a genuine dial of modulus 4 and carries one full bit.
"""

from __future__ import annotations

import cmath
import math
from collections import Counter
from typing import Callable, Dict, List, Tuple


def primes_up_to(limit: int) -> List[int]:
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, math.isqrt(limit) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    return [i for i, ok in enumerate(sieve) if ok]


def legendre(x: int, p: int) -> int:
    x %= p
    if x == 0:
        return 0
    return 1 if pow(x, (p - 1) // 2, p) == 1 else -1


def gauss_sum(p: int, a: int = 1) -> complex:
    """Quadratic Gauss sum with additive character twisted by a."""
    return sum(legendre(x, p) * cmath.exp(2j * cmath.pi * a * x / p) for x in range(p))


def entropy(counts: Counter) -> float:
    total = sum(counts.values())
    return -sum((c / total) * math.log2(c / total) for c in counts.values() if c)


def mutual_information(pairs: List[Tuple[object, object]]) -> float:
    """Empirical mutual information I(X;Y) in bits for a list of (x, y) samples."""
    n = len(pairs)
    joint = Counter(pairs)
    px = Counter(x for x, _ in pairs)
    py = Counter(y for _, y in pairs)
    return sum((c / n) * math.log2((c / n) / ((px[x] / n) * (py[y] / n)))
               for (x, y), c in joint.items())


def feature_study(primes: List[int], feature: Callable[[int], object], name: str) -> None:
    samples: List[Tuple[object, object]] = []
    for p in primes:
        samples.append((feature(p), p % 4))
    residue_entropy = entropy(Counter(y for _, y in samples))
    info = mutual_information(samples)
    values = sorted({str(x) for x, _ in samples})
    print(f"  feature: {name}")
    print(f"    distinct feature values : {len(values)}  {values[:4]}"
          f"{' ...' if len(values) > 4 else ''}")
    print(f"    H(residue class mod 4)  : {residue_entropy:.3f} bits")
    print(f"    I(feature ; residue)    : {info:.3f} bits")
    print()


def main() -> None:
    primes = [p for p in primes_up_to(120) if p != 2]
    print("Gauss-sum features over the odd primes below 120")
    print("=" * 60)

    def normalised_magnitude(p: int) -> str:
        # |g| / sqrt(p), rounded: provably 1 for every prime and every twist.
        return f"{abs(gauss_sum(p)) / math.sqrt(p):.6f}"

    def magnitude_over_twists(p: int) -> str:
        # the whole multiset of twisted magnitudes, normalised: still constant.
        vals = {round(abs(gauss_sum(p, a)) / math.sqrt(p), 6) for a in range(1, p)}
        return str(sorted(vals))

    def sign_of_g_squared(p: int) -> str:
        return "+" if (gauss_sum(p) ** 2).real > 0 else "-"

    feature_study(primes, normalised_magnitude, "normalised magnitude |g| / sqrt(p)")
    feature_study(primes, magnitude_over_twists, "multiset of twisted magnitudes")
    feature_study(primes, sign_of_g_squared, "sign of g^2")

    print("Reading:")
    print("  The magnitude features are constant, so their empirical mutual information")
    print("  with the residue class is 0 bits -- exactly as the theory predicts, since a")
    print("  constant feature accepts all residue classes or none and buys a scan speedup")
    print("  of exactly 1, strictly below the universal cap 4/3 for residue dials.")
    print("  The sign of g^2 attains the full residue entropy: it *is* the mod-4 dial.")


if __name__ == "__main__":
    main()

