"""Price Address Recovery by Iterated Parent Descent."""

from __future__ import annotations

import math
from typing import Tuple

Pair = Tuple[int, int]


def euclid_parameters(a: int, b: int, c: int) -> Pair:
    """Invert Euclid's parametrisation: (a,b,c) -> (m,n) with a = m^2-n^2, b = 2mn, c = m^2+n^2.

    Requires a primitive triple with a odd.  Raises ValueError otherwise.
    """
    if a % 2 == 0:
        a, b = b, a
    if a * a + b * b != c * c:
        raise ValueError("not a Pythagorean triple")
    if math.gcd(math.gcd(a, b), c) != 1:
        raise ValueError("triple is not primitive")
    m2, n2 = (c + a) // 2, (c - a) // 2
    m, n = math.isqrt(m2), math.isqrt(n2)
    if m * m != m2 or n * n != n2:
        raise ValueError("inconsistent triple")
    return (m, n)


def last_letter(p: Pair) -> str:
    """The final letter of the Price address of a non-root node.

    A  <=>  n even          (2-adic test)
    B  <=>  n odd, 2n < m   (archimedean test)
    C  <=>  n odd, 2n > m
    """
    m, n = p
    if n % 2 == 0:
        return "A"
    return "B" if 2 * n < m else "C"


def price_parent(p: Pair) -> Pair:
    """The unique Price parent of a non-root primitive parameter pair."""
    m, n = p
    if n % 2 == 0:
        return (m - n // 2, n // 2)
    if 2 * n < m:
        return (m // 2, m // 2 - n)
    return (m // 2, n - m // 2)


def price_address_from_parameters(p: Pair) -> str:
    """The unique Price address of a primitive parameter pair, as a word in {A,B,C}."""
    letters = []
    while p != (2, 1):
        letters.append(last_letter(p))
        p = price_parent(p)
    return "".join(reversed(letters))


def price_address(a: int, b: int, c: int) -> str:
    """The unique Price address of a primitive Pythagorean triple."""
    return price_address_from_parameters(euclid_parameters(a, b, c))


if __name__ == "__main__":
    for t in [(3, 4, 5), (5, 12, 13), (15, 8, 17), (7, 24, 25), (9, 40, 41),
              (585, 928, 1097), (4601, 4800, 6649)]:
        print(f"{t} -> address '{price_address(*t) or '(root)'}'")

"""Two-Adic Collision Certificate Generator."""

from __future__ import annotations

from typing import Dict, Tuple

Pair = Tuple[int, int]
Triple = Tuple[int, int, int]


def triple(p: Pair) -> Triple:
    """Euclid's triple of a parameter pair."""
    m, n = p
    return (m * m - n * n, 2 * m * n, m * m + n * n)


def price_children(p: Pair) -> Dict[str, Pair]:
    """Price moves: each doubles one parameter."""
    m, n = p
    return {"A": (m + n, 2 * n), "B": (2 * m, m - n), "C": (2 * m, m + n)}


def berggren_children(p: Pair) -> Dict[str, Pair]:
    """Berggren moves in Euclid parameter coordinates."""
    m, n = p
    return {"A": (2 * m - n, m), "B": (2 * m + n, m), "C": (m + 2 * n, n)}


def price_bc_collision(k: int) -> Dict[str, object]:
    """A B-child and a C-child of one node, distinct but congruent entrywise mod 2^k."""
    r: Pair = (2 ** k + 1, 2 ** k)
    kids = price_children(r)
    tb, tc = triple(kids["B"]), triple(kids["C"])
    return {
        "precision": 2 ** k,
        "node": r,
        "B_child_triple": tb,
        "C_child_triple": tc,
        "distinct": tb != tc,
        "congruent": all((x - y) % 2 ** k == 0 for x, y in zip(tb, tc)),
    }


def berggren_ab_collision(k: int) -> Dict[str, object]:
    """An A-child and a B-child of one node in Berggren's tree, congruent mod 2^k."""
    r: Pair = (2 ** k + 1, 2 ** k)
    kids = berggren_children(r)
    ta, tb = triple(kids["A"]), triple(kids["B"])
    return {
        "precision": 2 ** k,
        "node": r,
        "A_child_triple": ta,
        "B_child_triple": tb,
        "difference": tuple(y - x for x, y in zip(ta, tb)),
        "distinct": ta != tb,
        "congruent": all((x - y) % 2 ** k == 0 for x, y in zip(ta, tb)),
    }


if __name__ == "__main__":
    for k in range(1, 8):
        print("Price   ", price_bc_collision(k))
    for k in range(1, 5):
        print("Berggren", berggren_ab_collision(k))
